from mpi4py import MPI
comm = MPI.COMM_WORLD
if comm.Get_rank() == 0:
    params = {'timestep': 1e-6, 'tbr_target': 1.8}
else:
    params = None
params = comm.bcast(params, root=0)
# all ranks now share the same params dict

